#include "window.h"
#include <QtWidgets>
#include <QSqlQuery>
#include <QSqlError>
#include <set>
#include <QDesktopServices>
#include <stdexcept>
#include <QTimeZone>

void Window::capcodes(){
 QDialog dialog(this);dialog.setWindowTitle("GESTION DES CAPCODES ENREGISTRÉS");dialog.resize(1350,650);auto layout=new QVBoxLayout(&dialog);
 layout->addWidget(new QLabel("Journal TXT active la participation au fichier permanent configuré dans Enregistrements. Voix et affichage bas restent indépendants. Les anciens chemins individuels sont conservés sans servir aux nouveaux journaux."));
 auto search=new QLineEdit;search->setPlaceholderText("Rechercher un capcode, alias ou dossier…");layout->addWidget(search);
 auto table=new QTableWidget(0,19);table->setHorizontalHeaderLabels({"Capcode","Alias","Couleur","Actif","En bas","Fichier TXT direct","Description","Dossier dédié","Nom fichier TXT","Quotidien","Interprétation","Historique (jours)","Parcourir dossier","Parcourir TXT","Voix","Ouvrir dossier","Pager PrivateRadio (préparation)","Journal TXT","Ouvrir TXT"});layout->addWidget(table);for(int column:{5,7,8,9,12,13,15,18})table->setColumnHidden(column,true);
 auto append=[&](QStringList values){
  bool sorting=table->isSortingEnabled();table->setSortingEnabled(false);int row=table->rowCount();table->insertRow(row);
  for(int col=0;col<12;++col){if(col==10){auto combo=new QComboBox;combo->addItems({"INHERIT","ALPHA","NUMERIC","AUTO"});combo->setCurrentText(values.value(col,"INHERIT"));table->setCellWidget(row,col,combo);continue;}auto cell=new QTableWidgetItem(values.value(col));if(col==3||col==4||col==9)cell->setCheckState(values.value(col).toInt()?Qt::Checked:Qt::Unchecked);table->setItem(row,col,cell);}
  auto voice=new QTableWidgetItem;voice->setCheckState(values.value(12,"0").toInt()?Qt::Checked:Qt::Unchecked);table->setItem(row,14,voice);
  auto openFolder=new QPushButton("Ouvrir");table->setCellWidget(row,15,openFolder);connect(openFolder,&QPushButton::clicked,&dialog,[&,openFolder]{for(int r=0;r<table->rowCount();++r)if(table->cellWidget(r,15)==openFolder){QString path=table->item(r,7)->text().trimmed();if(path.isEmpty())path=QFileInfo(table->item(r,5)->text()).absolutePath();if(!QDir(path).exists()){QMessageBox::warning(&dialog,"Dossier","Ce dossier n'existe pas encore. Enregistrez sa configuration pour le créer.");return;}QDesktopServices::openUrl(QUrl::fromLocalFile(path));break;}});
  auto openTxt=new QPushButton("Ouvrir TXT");table->setCellWidget(row,18,openTxt);connect(openTxt,&QPushButton::clicked,&dialog,[&,openTxt]{for(int r=0;r<table->rowCount();++r)if(table->cellWidget(r,18)==openTxt){QString path=table->item(r,5)->text(),directory=table->item(r,7)->text();if(!directory.isEmpty()){QString filename=table->item(r,8)->text();if(filename.isEmpty())filename=QString("%1.txt").arg(table->item(r,0)->text().toUInt(),7,10,QChar('0'));if(table->item(r,9)->checkState()==Qt::Checked){auto date=QDateTime::currentDateTimeUtc().toTimeZone(QTimeZone("Europe/Brussels")).date().toString(Qt::ISODate);filename=date+"/"+QFileInfo(filename).completeBaseName()+"-"+date+".txt";}path=QDir(directory).filePath(filename);}if(path.isEmpty()||!QFileInfo::exists(path)){QMessageBox::information(&dialog,"TXT","Le fichier n'existe pas encore. Enregistrez la configuration puis attendez un message reçu.");return;}QDesktopServices::openUrl(QUrl::fromLocalFile(path));break;}});
  auto pager=new QTableWidgetItem;pager->setCheckState(values.value(13,"0").toInt()?Qt::Checked:Qt::Unchecked);pager->setToolTip("Préférence indépendante mémorisée ; aucun transfert réseau activé");table->setItem(row,16,pager);
  auto txtEnabled=new QTableWidgetItem;txtEnabled->setCheckState(values.value(14,"1").toInt()?Qt::Checked:Qt::Unchecked);table->setItem(row,17,txtEnabled);
  auto folder=new QPushButton("Parcourir…");table->setCellWidget(row,12,folder);connect(folder,&QPushButton::clicked,&dialog,[&,folder]{int row=-1;for(int r=0;r<table->rowCount();++r)if(table->cellWidget(r,12)==folder)row=r;if(row<0)return;QString path=QFileDialog::getExistingDirectory(&dialog,"Dossier de ce capcode",table->item(row,7)->text());if(!path.isEmpty()){table->item(row,7)->setText(path);if(table->item(row,8)->text().isEmpty())table->item(row,8)->setText(table->item(row,0)->text()+".txt");}});
  auto file=new QPushButton("Choisir TXT…");table->setCellWidget(row,13,file);connect(file,&QPushButton::clicked,&dialog,[&,file]{for(int r=0;r<table->rowCount();++r)if(table->cellWidget(r,13)==file){QString path=QFileDialog::getSaveFileName(&dialog,"Fichier TXT de ce capcode (ajout, création autorisée)",table->item(r,5)->text(),"Texte (*.txt)");if(!path.isEmpty()){table->item(r,5)->setText(path);table->item(r,7)->setText("");}break;}});table->setSortingEnabled(sorting);
 };
 QSqlQuery query("SELECT ric,alias,color,active,show_bottom,path,description,directory,filename,daily,interpretation,retention_days,voice_enabled,pager_enabled,txt_enabled FROM capcodes ORDER BY ric",db_);while(query.next()){QStringList values;values<<QString("%1").arg(query.value(0).toUInt(),7,10,QChar('0'));for(int col=1;col<15;++col)values<<query.value(col).toString();append(values);}query.finish();
 connect(search,&QLineEdit::textChanged,&dialog,[&](QString text){for(int r=0;r<table->rowCount();++r){bool matches=text.isEmpty();for(int c:{0,1,5,6,7,8})if(table->item(r,c)->text().contains(text,Qt::CaseInsensitive))matches=true;table->setRowHidden(r,!matches);}});
 auto rowValues=[&](int r){QStringList result;auto item=[&](int c){auto value=table->item(r,c);if(!value)throw std::runtime_error("Cellule de capcode manquante ; annulez puis rouvrez le dialogue");return value;};for(int c=0;c<12;++c){if(c==10){auto combo=qobject_cast<QComboBox*>(table->cellWidget(r,c));if(!combo)throw std::runtime_error("Interprétation de capcode manquante");result<<combo->currentText();}else if(c==3||c==4||c==9)result<<QString::number(item(c)->checkState()==Qt::Checked);else result<<item(c)->text().trimmed();}result<<QString::number(item(14)->checkState()==Qt::Checked)<<QString::number(item(16)->checkState()==Qt::Checked)<<QString::number(item(17)->checkState()==Qt::Checked);return result;};
 auto report=[&](QString reason){technical("Capcodes Save : "+reason);QMessageBox::warning(&dialog,"Enregistrement des capcodes impossible",reason+"\nLes données saisies sont conservées. Corrigez puis réessayez.");};

 auto bar=new QHBoxLayout;layout->addLayout(bar);auto add=new QPushButton("Ajouter");auto remove=new QPushButton("Supprimer");auto import=new QPushButton("Importer JSON");auto exportButton=new QPushButton("Exporter JSON");auto retention=new QPushButton("Appliquer la conservation enregistrée…");for(auto button:{add,remove,import,exportButton,retention})bar->addWidget(button);
 connect(add,&QPushButton::clicked,&dialog,[&]{append({"0000000","","#47d7ff","1","1","","","","","0","INHERIT","0"});});connect(remove,&QPushButton::clicked,&dialog,[&]{if(table->currentRow()>=0)table->removeRow(table->currentRow());});
 connect(import,&QPushButton::clicked,&dialog,[&]{QString path=QFileDialog::getOpenFileName(&dialog,"Importer capcodes",{},"JSON (*.json)");if(path.isEmpty())return;QFile file(path);if(!file.open(QIODevice::ReadOnly)){QMessageBox::warning(&dialog,"Import",file.errorString());return;}QJsonParseError error;auto doc=QJsonDocument::fromJson(file.readAll(),&error);if(error.error!=QJsonParseError::NoError||!doc.isArray()){QMessageBox::warning(&dialog,"Import","JSON invalide");return;}for(auto value:doc.array()){QStringList row;for(auto cell:value.toArray())row<<cell.toString();if(row.size()==7)row<<""<<""<<"0"<<"INHERIT"<<"0";if(row.size()==12)row<<"0";if(row.size()==13)row<<"0";if(row.size()==14)row<<"1";if(row.size()==15)append(row);}});
 connect(exportButton,&QPushButton::clicked,&dialog,[&]{QString path=QFileDialog::getSaveFileName(&dialog,"Exporter capcodes",{},"JSON (*.json)");if(path.isEmpty())return;try{QJsonArray rows;for(int r=0;r<table->rowCount();++r){QJsonArray values;for(auto value:rowValues(r))values.append(value);rows.append(values);}QSaveFile file(path);if(!file.open(QIODevice::WriteOnly)){QMessageBox::warning(&dialog,"Export",file.errorString());return;}auto bytes=QJsonDocument(rows).toJson();if(file.write(bytes)!=bytes.size()||!file.commit())report(file.errorString());}catch(const std::exception& e){report(QString::fromUtf8(e.what()));}});
 connect(retention,&QPushButton::clicked,&dialog,[&]{QString condition="ric IN (SELECT ric FROM capcodes WHERE retention_days>0 AND julianday('now')-julianday(messages.timestamp)>retention_days)";QSqlQuery count("SELECT count(*) FROM messages WHERE "+condition,db_);count.next();int total=count.value(0).toInt();count.finish();if(!total){QMessageBox::information(&dialog,"Conservation","Aucun message historique à purger selon les options déjà enregistrées.");return;}if(QMessageBox::question(&dialog,"Purge de l'historique",QString("Supprimer %1 messages SQLite selon les durées enregistrées ? Les fichiers TXT sont conservés.").arg(total))!=QMessageBox::Yes)return;QSqlQuery purge(db_);if(!purge.exec("DELETE FROM messages WHERE "+condition))QMessageBox::warning(&dialog,"Purge",purge.lastError().text());refresh();});
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
 connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{
  bool transaction=false;try{
   QVector<QStringList> rows;std::set<uint> ids;
   for(int r=0;r<table->rowCount();++r){auto values=rowValues(r);bool valid=false;uint ric=values[0].toUInt(&valid);bool daysValid=true;int days=values[11].isEmpty()?0:values[11].toInt(&daysValid);QString filename=values[8];if(!QRegularExpression("^[0-9]{1,7}$").match(values[0]).hasMatch()||!valid||ric>2097151||!ids.insert(ric).second||!QColor(values[2]).isValid()||!daysValid||days<0||days>365000)throw std::runtime_error("Capcode vide/invalide ou en double, couleur, nom TXT ou conservation incorrects");rows.push_back(values);}
   // Validate all rows before touching the database. A failed path never discards the dialog.
   // Legacy paths are preserved as metadata. Only the two journal destinations receive new messages.
   // Atomic snapshot of the previously committed capcodes, independent of WAL files.
   QJsonArray previous;QSqlQuery snapshot("SELECT ric,alias,color,active,show_bottom,path,description,directory,filename,daily,interpretation,retention_days,voice_enabled,pager_enabled,txt_enabled FROM capcodes ORDER BY ric",db_);if(snapshot.lastError().isValid())throw std::runtime_error(snapshot.lastError().text().toStdString());while(snapshot.next()){QJsonArray row;for(int c=0;c<15;++c)row.append(snapshot.value(c).toString());previous.append(row);}snapshot.finish();QSaveFile backup(QFileInfo(db_.databaseName()).absolutePath()+"/capcodes-backup.json");auto bytes=QJsonDocument(previous).toJson();if(!backup.open(QIODevice::WriteOnly)||backup.write(bytes)!=bytes.size()||!backup.commit())throw std::runtime_error(("Sauvegarde de secours impossible : "+backup.errorString()).toStdString());
   if(!db_.transaction())throw std::runtime_error(db_.lastError().text().toStdString());transaction=true;QSqlQuery clear(db_);if(!clear.exec("DELETE FROM capcodes"))throw std::runtime_error(clear.lastError().text().toStdString());
   for(auto values:rows){QSqlQuery insert(db_);insert.prepare("INSERT INTO capcodes(ric,alias,color,active,show_bottom,path,description,directory,filename,daily,interpretation,retention_days,voice_enabled,pager_enabled,txt_enabled) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");for(auto value:values)insert.addBindValue(value);if(!insert.exec())throw std::runtime_error(insert.lastError().text().toStdString());}
   if(!db_.commit())throw std::runtime_error(db_.lastError().text().toStdString());transaction=false;dialog.accept();refresh();
  }catch(const std::exception& e){if(transaction)db_.rollback();report(QString::fromUtf8(e.what()));}catch(...){if(transaction)db_.rollback();report("Exception inconnue pendant la sauvegarde");}
 });dialog.exec();
}

void Window::journal(){
 QDialog dialog(this);dialog.setWindowTitle("Enregistrements TXT — deux destinations indépendantes");dialog.resize(800,340);auto layout=new QVBoxLayout(&dialog);
 auto generalBox=new QGroupBox("Tous les messages — Toute la Belgique");auto g=new QFormLayout(generalBox);auto enabled=new QCheckBox("ON — création quotidienne, heure de Bruxelles");enabled->setChecked(generalCopy_->isChecked());auto root=new QLineEdit(root_->text());root->setObjectName("generalRoot");enabled->setObjectName("generalEnabled");g->addRow(enabled);g->addRow("Dossier principal",root);auto browse=new QPushButton("Parcourir…");auto open=new QPushButton("Ouvrir le dossier");auto generalButtons=new QHBoxLayout;generalButtons->addWidget(browse);generalButtons->addWidget(open);g->addRow(generalButtons);g->addRow(new QLabel("Belgique-AAAA-MM-JJ.txt — nouveau fichier à chaque date civile belge."));layout->addWidget(generalBox);
 auto selectedBox=new QGroupBox("Capcodes enregistrés et activés pour le journal TXT");auto f=new QFormLayout(selectedBox);auto selected=new QCheckBox("ON — ajout dans le fichier permanent");selected->setChecked(selectedLogging_->isChecked());auto path=new QLineEdit(selectedLogPath_->text());path->setObjectName("selectedJournalPath");selected->setObjectName("selectedEnabled");f->addRow(selected);f->addRow("Fichier TXT permanent",path);auto choose=new QPushButton("Parcourir…");auto openFile=new QPushButton("Ouvrir le fichier");auto buttonsRow=new QHBoxLayout;buttonsRow->addWidget(choose);buttonsRow->addWidget(openFile);f->addRow(buttonsRow);layout->addWidget(selectedBox);
 layout->addWidget(new QLabel("Format : CAPCODE DATE HEURE MESSAGE — UTF-8, une ligne par message, ajout sans conversion des anciennes lignes."));
 connect(browse,&QPushButton::clicked,&dialog,[&]{auto value=QFileDialog::getExistingDirectory(&dialog,"Dossier du journal général",root->text());if(!value.isEmpty())root->setText(value);});connect(choose,&QPushButton::clicked,&dialog,[&]{auto value=QFileDialog::getSaveFileName(&dialog,"Journal permanent (ajout, sans effacement)",path->text(),"Texte (*.txt)");if(!value.isEmpty())path->setText(value);});connect(open,&QPushButton::clicked,&dialog,[&]{QDesktopServices::openUrl(QUrl::fromLocalFile(root->text()));});connect(openFile,&QPushButton::clicked,&dialog,[&]{if(QFileInfo::exists(path->text()))QDesktopServices::openUrl(QUrl::fromLocalFile(path->text()));else QMessageBox::information(&dialog,"TXT","Le fichier sera créé à l'enregistrement de la configuration ou du premier message sélectionné.");});
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{if(enabled->isChecked()&&(!QDir::isAbsolutePath(root->text())||!QDir().mkpath(root->text()))){QMessageBox::warning(&dialog,"Dossier","Choisissez un dossier absolu accessible en écriture.");return;}if(selected->isChecked()){QFileInfo info(path->text());if(!info.isAbsolute()||info.fileName().isEmpty()||info.isDir()||info.fileName().endsWith('.')||info.fileName().endsWith(' ')||QRegularExpression("^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\\.|$)",QRegularExpression::CaseInsensitiveOption).match(info.fileName()).hasMatch()||path->text().contains(QRegularExpression("[<>|\"*?]"))||!QDir().mkpath(info.absolutePath())){QMessageBox::warning(&dialog,"Fichier","Choisissez un chemin TXT absolu valide.");return;}QFile file(path->text());if(!file.open(QIODevice::WriteOnly|QIODevice::Append)){QMessageBox::warning(&dialog,"TXT",file.errorString());return;}}
 root_->setText(root->text());selectedLogPath_->setText(path->text());generalCopy_->setChecked(enabled->isChecked());selectedLogging_->setChecked(selected->isChecked());saveOptions();dialog.accept();});dialog.exec();
}
